```openscad
// 8-place holder for 13 mm culture vials (printed upright)

// Block
block_len   = 170;   // X length
block_wid   = 30;    // Y width
block_ht    = 22;    // Z height

// Holes
n_holes     = 8;     // number of vial positions
pitch       = 20;    // centre-to-centre spacing along X
hole_d      = 13.3;  // hole diameter
hole_depth  = 18;    // blind hole depth from top (leaves 4 mm floor)
eps         = 0.5;   // overshoot past top face

$fn = 96;

difference() {
    // Solid block centred in X/Y, resting on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_ht]);

    // Row of blind holes along X, centred on the block
    for (i = [0 : n_holes - 1])
        translate([(i - (n_holes - 1)/2) * pitch, 0, block_ht - hole_depth])
            cylinder(d = hole_d, h = hole_depth + eps);
}
