// Push-on cap for 16.0 mm OD tube, printed open-end up
// All dimensions in mm

$fn = 96;

// --- Main body ---
cap_od        = 20.8;   // outer diameter of cap
cap_height    = 10;     // total height
bore_d        = 16.8;   // blind bore diameter (16.0 tube + 0.8 clearance)
floor_thick   = 2.5;    // closed end thickness at bottom

// --- Grip grooves ---
groove_count  = 12;     // number of vertical grooves
groove_d      = 2;      // groove diameter (half-cylinder centred on outer surface)

// --- Cutting overlap ---
eps           = 0.5;    // extension past faces for clean differences

difference() {
    // Main cylinder
    cylinder(d = cap_od, h = cap_height);

    // Blind bore from top
    translate([0, 0, floor_thick])
        cylinder(d = bore_d, h = cap_height - floor_thick + eps);

    // Vertical grip grooves, centred on the outer surface
    for (i = [0 : groove_count - 1])
        rotate([0, 0, i * 360 / groove_count])
            translate([cap_od / 2, 0, -eps])
                cylinder(d = groove_d, h = cap_height + 2 * eps, $fn = 48);
}
