```openscad
// Replacement control knob for 6.0 mm D-shaft
// Print orientation: hotplate-facing (bottom) side down on the bed, z = 0

// ---------------- Parameters ----------------
knob_d        = 28;    // knob outer diameter
knob_h        = 14;    // knob total height

bore_d        = 6.2;   // D-bore circle diameter (clearance for 6.0 mm shaft)
bore_flat     = 4.9;   // distance from flat to opposite side of bore circle
bore_depth    = 10;    // blind bore depth from bottom face

groove_n      = 16;    // number of grip grooves
groove_d      = 2;     // grip groove diameter (centred on outer surface)

eps           = 0.5;   // overshoot for clean boolean cuts
$fn           = 96;    // curve resolution

// Derived
bore_r        = bore_d / 2;
flat_y        = -bore_r + bore_flat;   // y position of the flat (from bore centre)

// ---------------- Model ----------------
difference() {
    // Main knob body
    cylinder(d = knob_d, h = knob_h);

    // D-shaped blind bore from the bottom face
    translate([0, 0, -eps])
        intersection() {
            cylinder(d = bore_d, h = bore_depth + eps);
            // keep everything below the flat
            translate([-bore_r - 1, -bore_r - 1, -eps])
                cube([bore_d + 2, flat_y + bore_r + 1, bore_depth + 3 * eps]);
        }

    // Vertical grip grooves around the circumference, full height
    for (i = [0 : groove_n - 1])
        rotate([0, 0, i * 360 / groove_n])
            translate([knob_d / 2, 0, -eps])
                cylinder(d = groove_d, h = knob_h + 2 * eps, $fn = 48);
}
