// Adapter sleeve: lets a narrow tube sit in a wider rack hole
// Print orientation: upside down, collar on the bed (z = 0), sleeve rising to z = 18.0

$fn = 96;               // facet count for round features

// ---- Dimensions (mm) ----
collar_d      = 15.0;   // collar outer diameter
collar_h      = 2.5;    // collar thickness (z = 0 to 2.5)
sleeve_od     = 13.0;   // sleeve body outer diameter
total_h       = 18.0;   // overall height (top of sleeve)
bore_d        = 10.0;   // straight through-bore diameter
eps           = 0.5;    // cutter overshoot past faces

difference() {
    union() {
        // Collar lying on the bed
        cylinder(d = collar_d, h = collar_h);
        // Sleeve body rising from the collar to the full height
        translate([0, 0, collar_h - 0.01])
            cylinder(d = sleeve_od, h = total_h - collar_h + 0.01);
    }
    // Through-bore, open at both ends
    translate([0, 0, -eps])
        cylinder(d = bore_d, h = total_h + 2 * eps);
}
