// Weighted base for vertical support rod
// Print orientation: upright, disc on bed (z = 0)

$fn = 96;

// --- Dimensions (mm) ---
base_d        = 60.0;   // base disc diameter
base_h        = 5.0;    // base disc thickness (z = 0 to 5)
boss_d        = 30.0;   // central boss diameter
boss_top_z    = 30.0;   // top of boss (overall height)
bore_d        = 8.0;    // rod bore diameter
bore_bottom_z = 5.0;    // blind bore floor height
screw_d       = 4.5;    // set-screw hole diameter
screw_z       = 24.0;   // set-screw hole centre height

eps           = 0.5;    // cutter overlap past faces

difference() {
    union() {
        // Base disc
        cylinder(d = base_d, h = base_h);
        // Central boss (overlaps disc slightly to ensure a single solid)
        translate([0, 0, base_h - 0.01])
            cylinder(d = boss_d, h = boss_top_z - base_h + 0.01);
    }

    // Blind rod bore from top down to z = 5
    translate([0, 0, bore_bottom_z])
        cylinder(d = bore_d, h = boss_top_z - bore_bottom_z + eps);

    // Radial set-screw hole from +X surface into the bore
    translate([0, 0, screw_z])
        rotate([0, 90, 0])
            cylinder(d = screw_d, h = boss_d / 2 + eps);
}
