// L-shaped mounting bracket
// Print orientation: base plate flat on the bed (z = 0), vertical plate rising in +Z.
// Coordinates follow the user's spec exactly (centred in X; Y runs 0..50 from back edge).

$fn = 64;

// ---------- Overall dimensions ----------
width      = 44;    // X extent (x from -22 to 22)
base_len   = 50;    // base plate Y extent (y from 0 to 50)
base_t     = 6;     // base plate thickness (z from 0 to 6)
vert_h     = 50;    // vertical plate height (z from 0 to 50)
vert_t     = 6;     // vertical plate thickness (y from 0 to 6)

// ---------- Holes ----------
hole_d     = 6.5;   // through-hole diameter
hole_x     = [-14, 14]; // X positions of holes (both plates)
base_hole_y = 35;   // Y position of base plate holes
vert_hole_z = 35;   // Z position of vertical plate holes

eps        = 0.5;   // overcut for clean boolean differences

difference() {
    union() {
        // Base plate
        translate([-width/2, 0, 0])
            cube([width, base_len, base_t]);
        // Vertical plate on back edge (y = 0)
        translate([-width/2, 0, 0])
            cube([width, vert_t, vert_h]);
    }

    // Vertical through-holes in base plate (along Z)
    for (x = hole_x)
        translate([x, base_hole_y, -eps])
            cylinder(d = hole_d, h = base_t + 2*eps);

    // Horizontal through-holes in vertical plate (along Y)
    for (x = hole_x)
        translate([x, -eps, vert_hole_z])
            rotate([-90, 0, 0])
                cylinder(d = hole_d, h = vert_t + 2*eps);
}
