```openscad
// 12-well agarose gel comb, printed flat on the bed
// All dimensions in mm

$fn = 64;

// --- Spine (back bar) ---
spine_len    = 90.0;   // spine length (X)
spine_w      = 8.0;    // spine width (Y)
thickness    = 2.0;    // plate thickness (Z, print height)

// --- Teeth ---
n_teeth      = 12;     // number of teeth / wells
tooth_w      = 4.0;    // tooth width (X)
tooth_len    = 10.0;   // tooth length (Y), hanging in -Y from spine
tooth_gap    = 3.0;    // gap between neighbouring teeth (X)
overlap      = 0.5;    // teeth extend into spine for a solid union

// --- Derived ---
tooth_pitch  = tooth_w + tooth_gap;                         // centre-to-centre spacing
teeth_span   = n_teeth * tooth_w + (n_teeth - 1) * tooth_gap; // total width of tooth row
total_y      = spine_w + tooth_len;                         // overall footprint in Y
y_bottom     = -total_y / 2;                                // tooth tips (footprint centred in Y)
y_spine0     = y_bottom + tooth_len;                        // spine lower edge

union() {
    // Spine
    translate([-spine_len / 2, y_spine0, 0])
        cube([spine_len, spine_w, thickness]);

    // Teeth, row centred on spine in X
    for (i = [0 : n_teeth - 1])
        translate([-teeth_span / 2 + i * tooth_pitch, y_bottom, 0])
            cube([tooth_w, tooth_len + overlap, thickness]);
}
```

