// Rigid in-line rod coupler, printed upright along Z
$fn = 96;

// ---- Dimensions (mm) ----
od          = 20.0;   // outer diameter of coupler
len         = 14.0;   // overall length (height along Z)
bore_d      = 4.0;    // axial bore diameter (rod size)
screw_d     = 6.0;    // radial set-screw hole diameter
screw_pos   = [0.25, 0.75]; // set-screw positions as fraction of length
eps         = 0.5;    // overcut for clean boolean differences

// ---- Model ----
difference() {
    // Main body
    cylinder(d = od, h = len);

    // Axial bore through full length
    translate([0, 0, -eps])
        cylinder(d = bore_d, h = len + 2 * eps);

    // Radial set-screw holes on +X side, from axis out through wall
    for (f = screw_pos)
        translate([0, 0, f * len])
            rotate([0, 90, 0])
                cylinder(d = screw_d, h = od / 2 + eps);
}
