```openscad
// Small lab funnel - printed upright, wide opening at top
// Built as a single rotate_extrude of a closed wall profile,
// so it is open at the top and at the bottom by construction.

$fn = 128;                 // smoothness of the revolved surfaces

// ---------------- Dimensions (mm) ----------------
spout_od      = 8.0;       // spout outer diameter
spout_h       = 25.0;      // spout height (z = 0 to z = 25)
rim_od        = 55.0;      // cone outer diameter at the rim
rim_z         = 60.0;      // rim height (top of funnel)
wall          = 1.6;       // wall thickness (normal to the wall)

// ---------------- Derived values ----------------
spout_r       = spout_od / 2;                 // 4.0  outer spout radius
bore_r        = spout_r - wall;               // 2.4  spout bore radius (4.8 mm bore)
rim_r         = rim_od / 2;                   // 27.5 outer rim radius
cone_h        = rim_z - spout_h;              // 35   cone height
cone_k        = (rim_r - spout_r) / cone_h;   // radial growth per mm of height
// Horizontal offset that gives a true 1.6 mm wall perpendicular to the cone surface
cone_off      = wall * sqrt(1 + cone_k * cone_k);
// Height where the inner cone surface meets the spout bore
join_z        = spout_h + (cone_off - wall) / cone_k;
rim_inner_r   = rim_r - cone_off;             // inner radius at the rim

// ---------------- Model ----------------
rotate_extrude(convexity = 4)
    polygon(points = [
        [bore_r,      0],        // bottom inner edge of spout
        [spout_r,     0],        // bottom outer edge of spout
        [spout_r,     spout_h],  // top of straight spout (outer)
        [rim_r,       rim_z],    // outer rim
        [rim_inner_r, rim_z],    // inner rim
        [bore_r,      join_z]    // inner cone meets spout bore
    ]);
