```openscad
// Flat drilling / marking jig
// Units: mm. Plate lies on XY plane at z = 0, centred on origin in X and Y.

$fn = 64;

// ---------------- Plate ----------------
plate_len   = 58;    // plate length along X
plate_wid   = 58;    // plate width along Y
plate_thk   = 5;     // plate thickness along Z

// ---------------- Hole grid ----------------
hole_d      = 4.0;   // through-hole diameter
hole_nx     = 4;     // number of holes along X
hole_ny     = 4;     // number of holes along Y
hole_pitch  = 10;    // centre-to-centre spacing (X and Y)

// ---------------- Orientation notch (+Y edge) ----------------
notch_w     = 12;    // notch width along X
notch_d     = 3;     // notch depth along Y, in from +Y edge

// ---------------- Cutting overshoot ----------------
eps         = 0.5;   // extension of cutters past cut faces

difference() {
    // Main plate
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // 4 x 4 grid of through-holes, centred on plate
    for (i = [0 : hole_nx - 1])
        for (j = [0 : hole_ny - 1])
            translate([(i - (hole_nx - 1)/2) * hole_pitch,
                       (j - (hole_ny - 1)/2) * hole_pitch,
                       -eps])
                cylinder(d = hole_d, h = plate_thk + 2*eps);

    // Rectangular orientation notch in +Y edge, centred on Y axis
    translate([-notch_w/2, plate_wid/2 - notch_d, -eps])
        cube([notch_w, notch_d + eps, plate_thk + 2*eps]);
}
```

```openscad
// Bench rack for 12 x 2.0 mL microcentrifuge tubes
// Print orientation: base on XY plane, holes open upward (+Z)

// ---------------- Parameters ----------------
block_x     = 74;    // block length (X), mm
block_y     = 60;    // block width (Y), mm
block_z     = 30;    // block height (Z), mm

cols        = 4;     // holes along X
rows        = 3;     // holes along Y
pitch       = 15;    // centre-to-centre spacing (X and Y), mm

hole_d      = 11.0;  // hole diameter, mm
hole_depth  = 25;    // hole depth from top face, mm
floor_t     = block_z - hole_depth; // solid floor thickness (5 mm)

overcut     = 0.5;   // extension of cutters past top face, mm
hole_fn     = 96;    // facets on holes

// ---------------- Derived ----------------
grid_x0 = -(cols - 1) * pitch / 2;  // first hole X (grid centred)
grid_y0 = -(rows - 1) * pitch / 2;  // first hole Y (grid centred)

// ---------------- Model ----------------
difference() {
    // Solid block, centred in XY, resting on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_z]);

    // Tube holes: blind, open at top, 5 mm floor
    for (i = [0 : cols - 1])
        for (j = [0 : rows - 1])
            translate([grid_x0 + i * pitch, grid_y0 + j * pitch, floor_t])
                cylinder(d = hole_d, h = hole_depth + overcut, $fn = hole_fn);
}
