```openscad
// Two-part enclosure: box + lid (lid printed upside down), side by side
$fn = 64;

// ---------- Box ----------
box_x      = 55.0;   // outer length (X)
box_y      = 40.0;   // outer width (Y)
box_z      = 25.0;   // outer height (Z)
wall_t     = 2.5;    // side wall thickness
floor_t    = 2.0;    // floor thickness

// ---------- Lid ----------
lid_x      = 55.0;   // lid plate length (X)
lid_y      = 40.0;   // lid plate width (Y)
lid_t      = 2.0;    // lid plate thickness
lip_x      = 49.6;   // lip outer length (X) = 50.0 opening - 2*0.2 clearance
lip_y      = 34.6;   // lip outer width (Y)  = 35.0 opening - 2*0.2 clearance
lip_wall   = 2.0;    // lip wall thickness
lip_h      = 4.0;    // lip height above plate

// ---------- Layout ----------
gap        = 10.0;   // gap between parts on the bed
eps        = 0.5;    // overcut for clean differences

total_x    = box_x + gap + lid_x;          // overall layout length
box_cx     = -total_x/2 + box_x/2;         // box centre X
lid_cx     =  total_x/2 - lid_x/2;         // lid centre X (+X side)

// ---------- Modules ----------
module box() {
    difference() {
        translate([-box_x/2, -box_y/2, 0])
            cube([box_x, box_y, box_z]);
        // inner cavity, open top
        translate([-(box_x - 2*wall_t)/2, -(box_y - 2*wall_t)/2, floor_t])
            cube([box_x - 2*wall_t, box_y - 2*wall_t, box_z - floor_t + eps]);
    }
}

module lid() {
    union() {
        // plate on the bed
        translate([-lid_x/2, -lid_y/2, 0])
            cube([lid_x, lid_y, lid_t]);
        // rectangular lip ring on top of the plate
        difference() {
            translate([-lip_x/2, -lip_y/2, lid_t - 0.01])
                cube([lip_x, lip_y, lip_h + 0.01]);
            translate([-(lip_x - 2*lip_wall)/2, -(lip_y - 2*lip_wall)/2, lid_t - eps])
                cube([lip_x - 2*lip_wall, lip_y - 2*lip_wall, lip_h + 2*eps]);
        }
    }
}

// ---------- Assembly on the bed ----------
translate([box_cx, 0, 0]) box();
translate([lid_cx, 0, 0]) lid();
```

