```openscad
// Replacement control knob for 6.3 mm D-shaft
// Print orientation: hotplate-facing side (bore opening) down on the bed

$fn = 96;

// ---- Knob body ----
knob_d      = 30;    // knob outer diameter
knob_h      = 14;    // knob total height

// ---- D-shaped blind bore ----
bore_d      = 6.5;   // bore circle diameter
bore_flat   = 5.2;   // distance from flat to opposite side of circle
bore_depth  = 11;    // blind bore depth from bottom face

// ---- Grip grooves ----
groove_n    = 20;    // number of grooves
groove_d    = 2;     // groove (half-cylinder) diameter, centred on outer surface

// ---- Helpers ----
eps         = 0.5;   // overshoot for clean boolean cuts

// Flat position measured from bore centre (+X side)
flat_x = bore_flat - bore_d / 2;

module d_bore() {
    translate([0, 0, -eps])
        linear_extrude(height = bore_depth + eps)
            intersection() {
                circle(d = bore_d);
                // keep everything from the far side up to the flat
                translate([-bore_d / 2 - 1, -bore_d / 2 - 1])
                    square([flat_x + bore_d / 2 + 1, bore_d + 2]);
            }
}

module grip_grooves() {
    for (i = [0 : groove_n - 1])
        rotate([0, 0, i * 360 / groove_n])
            translate([knob_d / 2, 0, -eps])
                cylinder(d = groove_d, h = knob_h + 2 * eps, $fn = 48);
}

difference() {
    cylinder(d = knob_d, h = knob_h);
    d_bore();
    grip_grooves();
}
