```openscad
// Weighted base with vertical support rod holder
// Print orientation: upright, disc on bed (z = 0)

$fn = 96;

// ---- Base disc ----
disc_d      = 60.0;   // base disc diameter
disc_h      = 8.0;    // base disc thickness (z = 0 to 8)

// ---- Central boss ----
boss_d      = 18.0;   // boss diameter
boss_top_z  = 30.0;   // top of boss (z)

// ---- Rod bore ----
bore_d      = 12.0;   // blind bore diameter for rod
bore_bot_z  = 8.0;    // bottom of blind bore (z)

// ---- Set-screw hole ----
screw_d     = 5.0;    // radial set-screw hole diameter
screw_z     = 24.0;   // set-screw hole centre height

// ---- Cutting overlap ----
eps         = 0.5;    // extension past cut faces

difference() {
    union() {
        // Base disc
        cylinder(d = disc_d, h = disc_h);
        // Boss (overlaps into disc to fuse solids)
        translate([0, 0, disc_h - eps])
            cylinder(d = boss_d, h = boss_top_z - disc_h + eps);
    }

    // Blind bore from top of boss down to z = 8
    translate([0, 0, bore_bot_z])
        cylinder(d = bore_d, h = boss_top_z - bore_bot_z + eps);

