lip_h     = 4;     // lip height above plate

// ---------- Layout ----------
gap       = 10;    // gap between parts on the bed
eps       = 0.5;   // cutter overshoot
fuse      = 0.01;  // small overlap to fuse lip into plate

// Part centres in X, so the pair is centred on the origin
