        translate([-box_x/2, -box_y/2, 0])
            cube([box_x, box_y, box_z]);
        // cavity, open at the top
        translate([-(box_x - 2*wall_t)/2, -(box_y - 2*wall_t)/2, floor_t])
            cube([box_x - 2*wall_t, box_y - 2*wall_t, box_z - floor_t + eps]);
    }
}

// ---------- Part 2: Lid (printed upside down) ----------
module lid() {
    union() {
        // plate on the bed
        translate([-lid_x/2, -lid_y/2, 0])
            cube([lid_x, lid_y, lid_t]);
        // rectangular lip wall
        translate([0, 0, lid_t - fuse])
            difference() {
                translate([-lip_x/2, -lip_y/2, 0])
                    cube([lip_x, lip_y, lip_h + fuse]);
                translate([-(lip_x - 2*lip_wall)/2, -(lip_y - 2*lip_wall)/2, -eps])
                    cube([lip_x - 2*lip_wall, lip_y - 2*lip_wall, lip_h + fuse + 2*eps]);
            }
    }
}

