// Small lab funnel - printed upright, wide opening at top
// Built as a rotate_extrude of the wall cross-section (open at both ends)

$fn = 128;                         // smoothness of round surfaces

// ---------------- Dimensions (mm) ----------------
wall        = 1.2;                 // wall thickness (normal to surface)
spout_od    = 12.0;                // spout outer diameter
spout_h     = 15;                  // spout height (z = 0 .. 15)
rim_od      = 45;                  // cone outer diameter at rim
rim_z       = 55;                  // rim height (top of funnel)

// ---------------- Derived values ----------------
spout_ro    = spout_od / 2;                    // spout outer radius (6.0)
spout_ri    = spout_ro - wall;                 // spout bore radius (4.8 -> 9.6 bore)
rim_ro      = rim_od / 2;                      // rim outer radius (22.5)
cone_h      = rim_z - spout_h;                 // cone height (40)
cone_slope  = (rim_ro - spout_ro) / cone_h;    // radial growth per mm of z
// horizontal offset that gives a 1.2 mm wall measured normal to the cone surface
cone_dr     = wall * sqrt(1 + cone_slope * cone_slope);
rim_ri      = rim_ro - cone_dr;                // inner radius at rim
// height where the inner cone surface meets the spout bore
join_z      = spout_h + (cone_dr - wall) / cone_slope;

// ---------------- Model ----------------
rotate_extrude(convexity = 4)
    polygon(points = [
        [spout_ri, 0],         // bottom of bore
        [spout_ro, 0],         // bottom outer edge
        [spout_ro, spout_h],   // spout / cone outer junction
        [rim_ro,   rim_z],     // rim outer edge
        [rim_ri,   rim_z],     // rim inner edge
        [spout_ri, join_z]     // inner cone meets bore
    ]);
