flat_y   = -bore_r + bore_flat_ac;   // Y position of the flat (opposite side at -bore_r)

// 2D D-profile
module d_profile() {
    intersection() {
        circle(r = bore_r, $fn = 96);
        translate([-bore_r - 1, -bore_r - 1])
            square([bore_d + 2, (flat_y) - (-bore_r - 1)]);
    }
}

