// Small lab funnel - printed upright, wide opening at top
// Built as a single rotate_extrude profile (no boolean cuts needed)

$fn = 128;

// ---------------- Dimensions (mm) ----------------
spout_od      = 8.0;    // spout outer diameter
spout_h       = 25.0;   // spout height (z = 0 .. 25)
rim_od        = 70.0;   // cone outer diameter at rim
total_h       = 50.0;   // overall height (rim at z = 50)
wall          = 1.2;    // wall thickness (normal to surface)

// ---------------- Derived values ----------------
r_spout_out   = spout_od / 2;                 // 4.0
r_spout_in    = r_spout_out - wall;           // 2.8 -> 5.6 mm bore
r_rim_out     = rim_od / 2;                   // 35.0
cone_h        = total_h - spout_h;            // 25.0
cone_slope    = (r_rim_out - r_spout_out) / cone_h;   // dr/dz
// radial offset that gives a true 1.2 mm wall normal to the cone surface
cone_radial_t = wall * sqrt(1 + cone_slope * cone_slope);
r_rim_in      = r_rim_out - cone_radial_t;    // inner radius at rim
// height where the inner cone surface meets the spout bore
z_join_in     = spout_h + (cone_radial_t - wall) / cone_slope;

// ---------------- Model ----------------
rotate_extrude(convexity = 4)
    polygon(points = [
        [r_spout_in, 0],            // bottom of bore
        [r_spout_out, 0],           // bottom outer edge of spout
        [r_spout_out, spout_h],     // spout / cone outer junction
        [r_rim_out, total_h],       // outer rim
        [r_rim_in, total_h],        // inner rim
        [r_spout_in, z_join_in]     // inner cone meets bore
    ]);
