// Flat drilling/marking jig
// Plate with 3 x 5 grid of through-holes and an orientation notch on the +Y edge

$fn = 64;

// ---------- Plate ----------
plate_x     = 54;    // plate length along X (mm)
plate_y     = 84;    // plate width along Y (mm)
plate_t     = 3;     // plate thickness along Z (mm)

// ---------- Hole grid ----------
hole_d      = 3.0;   // through-hole diameter (mm)
hole_cols   = 3;     // number of holes along X
hole_rows   = 5;     // number of holes along Y
hole_pitch_x = 15;   // centre-to-centre spacing along X (mm)
hole_pitch_y = 15;   // centre-to-centre spacing along Y (mm)

// ---------- Orientation notch (+Y edge) ----------
notch_w     = 12;    // notch width along X (mm)
notch_d     = 4;     // notch depth along Y, from the +Y edge (mm)

// ---------- Cutting overshoot ----------
eps         = 0.5;   // extra length on cutters to avoid coplanar faces (mm)

// Derived: offsets so the grid is centred on the origin
grid_x0 = -(hole_cols - 1) * hole_pitch_x / 2;
grid_y0 = -(hole_rows - 1) * hole_pitch_y / 2;

difference() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_x / 2, -plate_y / 2, 0])
        cube([plate_x, plate_y, plate_t]);

    // 3 x 5 grid of through-holes
    for (i = [0 : hole_cols - 1])
        for (j = [0 : hole_rows - 1])
            translate([grid_x0 + i * hole_pitch_x,
                       grid_y0 + j * hole_pitch_y,
                       -eps])
                cylinder(d = hole_d, h = plate_t + 2 * eps, $fn = 64);

    // Rectangular orientation notch in the +Y edge, centred on the Y axis
    translate([-notch_w / 2,
               plate_y / 2 - notch_d,
               -eps])
        cube([notch_w, notch_d + eps, plate_t + 2 * eps]);
}
